begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select is((select count(*) from private.pilot_account_admission),0::bigint,'roster initially empty');
select is((select count(*) from private.pilot_admission_managers),0::bigint,'managers initially empty');
select is((select enabled from private.pilot_availability),false,'availability initially off');
select is((select count(*) from private.pilot_capabilities where not enabled and revision=1),13::bigint,'all fixed capabilities off revision one');
select ok(not private.pilot_is_available(),'private availability helper closed');
select ok(not private.pilot_capability_enabled('unknown'),'unknown capability denied');
select ok(not private.pilot_caller_is_admitted(),'missing caller denied');
select ok(not has_schema_privilege('anon','private','USAGE'),'anon private schema unavailable');
select ok((select bool_and(not has_table_privilege('authenticated','private.'||t,'SELECT,INSERT,UPDATE,DELETE')) from unnest(array['pilot_account_admission','pilot_admission_managers','pilot_availability','pilot_capabilities','pilot_management_audit','pilot_management_requests','pilot_manager_audit']) t),'all private tables lack client grants');
select ok((select bool_and(relrowsecurity) from pg_class where oid in (select ('private.'||t)::regclass from unnest(array['pilot_account_admission','pilot_admission_managers','pilot_availability','pilot_capabilities','pilot_management_audit','pilot_management_requests','pilot_manager_audit']) t)),'all authority tables RLS enabled');
select ok(not has_function_privilege('anon','public.set_pilot_policy(text,boolean,bigint,text,uuid)','EXECUTE'),'anon cannot execute management');
select ok(not has_function_privilege('service_role','private.set_pilot_manager_fixture(uuid,text,bigint,text,uuid)','EXECUTE'),'service role cannot bootstrap manager');
select ok(not has_function_privilege('authenticated','private.pilot_require_manager()','EXECUTE'),'private manager helper not client executable');
select ok(to_regprocedure('public.set_pilot_account_admission(uuid,uuid,text,bigint,text,uuid)') is null,'no fabricated actor signature');
insert into auth.users(id,email,email_confirmed_at)
select ('55000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'pilot-sql-'||n||'@unc.edu',now() from generate_series(1,8) n;
update auth.users set email_confirmed_at=null where id='55000000-0000-4000-8000-000000000003';
update auth.users set email='pilot-sql-4@unc.edu.evil.test' where id='55000000-0000-4000-8000-000000000004';
update public.accounts set status='suspended' where id='55000000-0000-4000-8000-000000000005';
insert into public.platform_roles(user_id,role) values('55000000-0000-4000-8000-000000000006','admin');
select is(private.set_pilot_manager_fixture('55000000-0000-4000-8000-000000000001','active',0,'Local test executor',gen_random_uuid()),1::bigint,'trusted manager bootstrap');
select is((select executor_session_user from private.pilot_manager_audit),'postgres','bootstrap records actual executor');
select ok((select executor_original_role in ('none','postgres') and executor_backend_pid=pg_backend_pid() from private.pilot_manager_audit),'original SQL role and backend provenance');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','active',0,'test',gen_random_uuid())$$,'42501','Pilot management unavailable','ordinary verified user denied');
select throws_ok($$select * from private.pilot_account_admission$$,'42501',null,'direct roster read denied');
select throws_ok($$insert into private.pilot_admission_managers(account_id,state,revision) values(auth.uid(),'active',1)$$,'42501',null,'self manager assignment denied');
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select throws_ok($$select * from public.set_pilot_policy('availability',true,1,'test',gen_random_uuid())$$,'42501','Pilot management unavailable','platform admin without manager denied');
reset role;
set local role anon;
select throws_ok($$select private.set_pilot_manager_fixture('55000000-0000-4000-8000-000000000002','active',0,'forge',gen_random_uuid())$$,'42501',null,'actual anon role bootstrap denied');
reset role;
set local role service_role;
select throws_ok($$select private.set_pilot_manager_fixture('55000000-0000-4000-8000-000000000002','active',0,'forge',gen_random_uuid())$$,'42501',null,'actual service_role bootstrap execute denied');
reset role;
grant usage on schema private to service_role;
grant execute on function private.set_pilot_manager_fixture(uuid,text,bigint,text,uuid) to service_role;
set local role service_role;
select throws_ok($$select private.set_pilot_manager_fixture('55000000-0000-4000-8000-000000000002','active',0,'forge',gen_random_uuid())$$,'42501','Pilot management unavailable','original service_role guard independent of execute permission');
reset role;
revoke execute on function private.set_pilot_manager_fixture(uuid,text,bigint,text,uuid) from service_role;
revoke usage on schema private from service_role;
grant usage on schema private to anon;
grant execute on function private.set_pilot_manager_fixture(uuid,text,bigint,text,uuid) to anon;
set local role anon;
select throws_ok($$select private.set_pilot_manager_fixture('55000000-0000-4000-8000-000000000002','active',0,'forge',gen_random_uuid())$$,'42501','Pilot management unavailable','original anon role guard independent of schema and execute permission');
reset role;
revoke execute on function private.set_pilot_manager_fixture(uuid,text,bigint,text,uuid) from anon;
revoke usage on schema private from anon;
-- Grant only inside rolled-back test to prove original-role guard independently
-- of EXECUTE revokes under postgres session SET ROLE authenticated.
grant execute on function private.set_pilot_manager_fixture(uuid,text,bigint,text,uuid) to authenticated;
set local role authenticated;
select throws_ok($$select private.set_pilot_manager_fixture('55000000-0000-4000-8000-000000000002','active',0,'forged',gen_random_uuid())$$,'42501','Pilot management unavailable','SECURITY DEFINER does not erase original-role guard');
reset role;
revoke execute on function private.set_pilot_manager_fixture(uuid,text,bigint,text,uuid) from authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select revision from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','active',0,U&'\00A0Reason\00A0','55000000-0000-4000-8001-000000000001')),1::bigint,'manager admits verified incomplete target with gates off');
select is((select revision from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','active',0,'Reason','55000000-0000-4000-8001-000000000001')),1::bigint,'normalized exact retry returns original receipt');
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select * from public.set_pilot_policy('availability',true,1,'self',gen_random_uuid())$$,'42501','Pilot management unavailable','ordinary admitted student has no manager authority');
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','revoked',0,'Reason','55000000-0000-4000-8001-000000000001')$$,'42501','Pilot management unavailable','changed request payload denies');
select throws_ok($$select * from public.set_pilot_policy('availability',true,1,'Reason','55000000-0000-4000-8001-000000000001')$$,'42501','Pilot management unavailable','cross-operation request UUID denies');
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','active',0,'Reason',gen_random_uuid())$$,'42501','Pilot management unavailable','stale creation revision denies');
select is((select revision from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','active',1,'Noop',gen_random_uuid())),1::bigint,'new same-state request no-op revision unchanged');
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000003','active',0,'test',gen_random_uuid())$$,'42501','Pilot management unavailable','unconfirmed target denies');
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000004','active',0,'test',gen_random_uuid())$$,'42501','Pilot management unavailable','wrong exact domain denies');
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000005','active',0,'test',gen_random_uuid())$$,'42501','Pilot management unavailable','inactive target denies');
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','invalid',1,'test',gen_random_uuid())$$,'42501','Pilot management unavailable','invalid state denied');
select throws_ok($$select * from public.set_pilot_policy('unknown',true,1,'test',gen_random_uuid())$$,'42501','Pilot management unavailable','unknown key denied');
select throws_ok($$select * from public.set_pilot_policy('availability',true,null,'test',gen_random_uuid())$$,'42501','Pilot management unavailable','expected revision mandatory');
select throws_ok($$select * from public.set_pilot_policy('availability',true,1,'   ',gen_random_uuid())$$,'42501','Pilot management unavailable','blank reason denied');
select throws_ok($$select * from public.set_pilot_policy('availability',true,1,repeat('x',2001),gen_random_uuid())$$,'42501','Pilot management unavailable','oversized reason denied');
reset role;
update auth.users set email='manager-not-student@example.test' where id='55000000-0000-4000-8000-000000000001';
update public.universities set active=false where slug='unc-chapel-hill';
set local role authenticated;
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000008','active',0,'inactive campus',gen_random_uuid())$$,'42501','Pilot management unavailable','inactive target campus denies activation');
reset role;
update public.universities set active=true where slug='unc-chapel-hill';
set local role authenticated;
select is((select revision from public.set_pilot_policy('availability',true,1,'enabled','55000000-0000-4000-8001-000000000002')),2::bigint,'policy change CAS revision; manager needs no student verification');
select is((select revision from public.set_pilot_policy('availability',true,1,'enabled','55000000-0000-4000-8001-000000000002')),2::bigint,'policy exact retry');
select is((select revision from public.set_pilot_policy('availability',true,2,'noop',gen_random_uuid())),2::bigint,'policy noop unchanged revision');
select is((select revision from public.set_pilot_policy('onboarding',true,1,'enabled',gen_random_uuid())),2::bigint,'allowed capability change');
select throws_ok($$select * from public.set_pilot_policy('onboarding',false,1,'stale',gen_random_uuid())$$,'42501','Pilot management unavailable','capability stale CAS');
reset role;
select is((select count(*) from private.pilot_management_audit where target_id='55000000-0000-4000-8000-000000000002'),2::bigint,'only new admission and normalized noop audited; retry/failed calls append none');
select is((select reason from private.pilot_management_audit where request_id='55000000-0000-4000-8001-000000000001'),'Reason','audit reason normalized');
select is((select count(*) from private.pilot_management_requests),5::bigint,'successful operations each one receipt');
select ok((select bool_and(actor_id='55000000-0000-4000-8000-000000000001') from private.pilot_management_audit),'actual manager actor attributable');
select throws_ok($$update private.pilot_management_audit set reason='rewrite'$$,'42501','Pilot evidence is immutable','even privileged ordinary audit rewrite denied');
select throws_ok($$delete from private.pilot_management_requests$$,'42501','Pilot evidence is immutable','receipt deletion denied');
select throws_ok($$delete from private.pilot_manager_audit$$,'42501','Pilot evidence is immutable','manager audit deletion denied');
update auth.users set email='lost@example.test' where id='55000000-0000-4000-8000-000000000002';
set local role authenticated;
select is((select revision from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','revoked',1,'lost email',gen_random_uuid())),2::bigint,'revocation after target verification loss succeeds');
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','active',2,'reactivate',gen_random_uuid())$$,'42501','Pilot management unavailable','reactivation requires live verified target');
reset role;
update auth.users set email='pilot-sql-2@unc.edu' where id='55000000-0000-4000-8000-000000000002';
set local role authenticated;
select is((select revision from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','active',2,'reactivate',gen_random_uuid())),3::bigint,'explicit reactivation increments once');
select is((select count(*) from public.profiles where user_id='55000000-0000-4000-8000-000000000002'),0::bigint,'manager has no target profile reader');
reset role;
insert into storage.objects(bucket_id,name,owner_id) values('profile-photos','55000000-0000-4000-8000-000000000002/private.png','55000000-0000-4000-8000-000000000002');
insert into public.hangouts(id,university_id,host_id,title,starts_at,public_place,public_latitude,public_longitude) values('55000000-0000-4000-8002-000000000001','00000000-0000-4000-8000-000000000001','55000000-0000-4000-8000-000000000002','Private fixture',now()+interval '1 hour','Area',35,-79);
insert into public.hangout_private_locations(hangout_id,instructions) values('55000000-0000-4000-8002-000000000001','Retained private instructions');
update private.hangout_feature_gate set enabled=true;
update private.hangout_chat_feature_gate set enabled=true;
set local role authenticated;
select is((select count(*) from storage.objects where name='55000000-0000-4000-8000-000000000002/private.png'),0::bigint,'manager authority gives no target photo read');
select is((select count(*) from public.hangout_private_locations where hangout_id='55000000-0000-4000-8002-000000000001'),0::bigint,'manager authority gives no private-place read with source gate on');
select throws_ok($$select * from public.read_hangout_messages('55000000-0000-4000-8002-000000000001')$$,'42501',null,'manager authority gives no chat reader with legacy gates on');
select throws_ok($$insert into private.pilot_management_audit(actor_id,operation,new_value,previous_revision,new_revision,reason,request_id) values(auth.uid(),'policy','true',0,1,'forge',gen_random_uuid())$$,'42501',null,'client audit insert denied');
reset role;
select is(private.set_pilot_manager_fixture('55000000-0000-4000-8000-000000000007','active',0,'second manager',gen_random_uuid()),1::bigint,'second manager setup');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000007","role":"authenticated"}',true);
select is((select revision from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000008','revoked',0,'other actor','55000000-0000-4000-8001-000000000001')),1::bigint,'same UUID different actor creates isolated receipt');
reset role;
select is(private.set_pilot_manager_fixture('55000000-0000-4000-8000-000000000001','revoked',1,'local revoke',gen_random_uuid()),2::bigint,'trusted manager revocation audited');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select * from public.set_pilot_account_admission('55000000-0000-4000-8000-000000000002','active',0,'Reason','55000000-0000-4000-8001-000000000001')$$,'42501','Pilot management unavailable','revoked manager exact retry denies before receipt');
reset role;
delete from private.pilot_capabilities where key='onboarding';
select ok(not private.pilot_capability_enabled('onboarding'),'missing capability helper fails closed');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000007","role":"authenticated"}',true);
select throws_ok($$select * from public.set_pilot_policy('onboarding',true,0,'missing',gen_random_uuid())$$,'42501','Pilot management unavailable','missing seeded capability is never recreated');
reset role;
delete from private.pilot_availability;
select ok(not private.pilot_is_available(),'missing singleton helper fails closed');
select ok(not private.pilot_capability_enabled('onboarding'),'missing singleton capability fails closed');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000007","role":"authenticated"}',true);
select throws_ok($$select * from public.set_pilot_policy('availability',true,0,'missing',gen_random_uuid())$$,'42501','Pilot management unavailable','missing singleton is never recreated');
reset role;
delete from auth.users where id='55000000-0000-4000-8000-000000000007';
select is((select count(*) from private.pilot_admission_managers where account_id='55000000-0000-4000-8000-000000000007'),0::bigint,'account delete cascades live manager');
select is((select count(*) from private.pilot_management_requests where actor_id='55000000-0000-4000-8000-000000000007'),1::bigint,'account delete retains private historical receipt UUID');
delete from auth.users where id='55000000-0000-4000-8000-000000000008';
select is((select count(*) from private.pilot_account_admission where account_id='55000000-0000-4000-8000-000000000008'),0::bigint,'target deletion cascades live admission without new restriction');
select * from finish();
rollback;
